// Hand-drawn split-card lyric subtitles. Cards are generated by `npm run prepare`
// into generated/subtitle-cards.json; this module only draws them as elements
// INSIDE the same painted space (ink, 12 Hz boiling, watercolour, paper grain).
import { C, rgba, mix } from './core/palette.mjs';
import { W, H } from './core/camera.mjs';
import { VERTICAL, HERO_BOX } from './core/layout.mjs';
import { CONFIG, readGenerated } from './core/config.mjs';
import { fontOf } from './core/font.mjs';
import { thin, brush, contour, fillPoly, resample, poly } from './core/ink.mjs';
import { softPatch, wash } from './core/paint.mjs';
import { clamp, smooth, easeOutCubic, easeOutBack, boil, noise1, TAU, lerp } from './core/math.mjs';
import { pulse, BEAT } from './timeline/spec.mjs';

export const CARDS = readGenerated('cards').cards;

// Font registration (Latin + CJK handwriting) lives in core/font.mjs so diagrams
// and lyric cards share exactly the same letterforms.
export const BASE_PX = VERTICAL ? 50 : 48;
const MARGIN_X = VERTICAL ? 54 : 96;
const MARGIN_Y = VERTICAL ? 96 : 54;
const KF_CAP = VERTICAL ? 2.25 : 2.8;

const ZONES = {
  Z1: [0.22, 0.20, 0], Z2: [0.50, 0.17, 0], Z3: [0.78, 0.21, 0],
  Z4: [0.18, 0.50, 0], Z5: [0.50, 0.50, 0], Z6: [0.82, 0.50, 0],
  Z7: [0.24, 0.80, 0], Z8: [0.76, 0.79, 0], Z9: [0.50, 0.50, -0.26],
  Z10: [0.50, 0.50, 0.12], Z11: [0.86, 0.50, 0], Z12: [0.50, 0.50, 0.09],
};
const ZONE_NAMES = Object.keys(ZONES);
// Tutorial films can keep all key-phrase cards in one caption band below the
// diagram. The zone still drives a distinct horizontal slot (12 of them) plus
// a 3-row vertical offset, so nothing is static or repeated. Music films leave
// this unset and use the full-canvas Z1–Z12 distribution.
const BAND = CONFIG.style?.cardBand || null;
const TEX = {
  dry:    { ink: mix(C.violet, C.ink, 0.58), fill: rgba(C.violet, 0.28), strokeW: 1.2, wet: false, grain: 1.0 },
  wet:    { ink: C.ink,                      fill: rgba(C.ochre, 0.46),  strokeW: 1.7, wet: true,  grain: 0.35 },
  mid:    { ink: mix(C.clayDk, C.ink, 0.55), fill: rgba(C.teal, 0.38),   strokeW: 1.4, wet: true,  grain: 0.6 },
  bright: { ink: C.ink,                      fill: rgba(C.ochre, 0.60),  strokeW: 1.9, wet: true,  grain: 0.2 },
};

const S0 = () => ({ alpha: 1, scale: 1, dx: 0, dy: 0, rot: 0, clip: 1, scatter: 0, flip: 0, rise: 0, swirl: 0, bubble: 0, circleClip: 0 });
function enterState(c, age) {
  const S = S0(), u = clamp(age / (c.tailException ? 0.12 : 0.34)), k = easeOutCubic(u);
  switch (c.enter) {
    case 'E1': S.clip = k; break;
    case 'E2': S.scale = Math.max(0.001, easeOutBack(u, 1.7)); S.alpha = clamp(u * 2.4); break;
    case 'E3': S.dy = -(1 - k) * 125; S.scatter = (1 - k) * 0.55; break;
    case 'E4': S.dx = -(1 - k) * W * 0.22; S.dy = -Math.sin(u * Math.PI) * 46; break;
    case 'E5': S.alpha = k; S.swirl = 1 - k; break;
    case 'E6': S.clip = k; break;
    case 'E7': S.flip = Math.sin(u * Math.PI); break;
    case 'E8': S.scale = Math.max(0.001, k); break;
    case 'E9': S.clip = k; S.rise = 1 - k; break;
    case 'E10': S.dy = (1 - k) * 95; S.scale = 0.62 + 0.38 * k; S.bubble = 1 - k; break;
    case 'E11': S.circleClip = k; break;
    case 'E12': S.scatter = 1 - k; S.rot = (1 - k) * 0.13; break;
  }
  return S;
}
function exitState(c, left) {
  const S = S0(), k = 1 - clamp(left / 0.30);
  switch (c.exit) {
    case 'E1': S.clip = 1 - k; break;
    case 'E2': S.scale = 1 + 0.22 * Math.sin(k * Math.PI) - 0.9 * k * k; break;
    case 'E3': S.dy = -k * 80; S.scatter = k * 0.5; break;
    case 'E4': S.dx = k * W * 0.20; S.dy = -Math.sin(k * Math.PI) * 42; break;
    case 'E5': S.alpha = 1 - k; S.swirl = k; break;
    case 'E6': S.clip = 1 - k; break;
    case 'E7': S.flip = Math.sin(k * Math.PI); break;
    case 'E8': S.scale = Math.max(0.001, 1 - k); break;
    case 'E9': S.alpha = 1 - k * 0.9; S.rise = k; break;
    case 'E10': S.alpha = 1 - k; S.dy = -k * 110; S.bubble = k; break;
    case 'E11': S.circleClip = 1 - k; break;
    case 'E12': S.scatter = k; S.rot = k * 0.14; break;
  }
  return S;
}

function formBack(g, c, fontPx, tex, t, width) {
  const hw = width / 2 + 26, hh = fontPx * 0.82;
  if (c.form === 'F5') {
    const pts = [], n = 24;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * TAU, lobe = 1 + 0.10 * Math.sin(a * 6 + 1.2);
      pts.push([Math.cos(a) * hw * lobe, Math.sin(a) * hh * lobe]);
    }
    fillPoly(g, resample(pts, 10, true), rgba(C.creamLite, 0.86), 1);
    contour(g, pts, { t, seed: 1500 + c.id, w: 2.2, color: rgba(C.indigo, 0.85), wobble: 0.8 });
    thin(g, [[-hw * 0.35, hh * 0.9], [-hw * 0.15, hh * 1.5], [hw * 0.05, hh * 0.95]], { t, seed: 1510 + c.id, w: 2, color: rgba(C.indigo, 0.7) });
  } else if (c.form === 'F6') {
    const top = [], bot = [];
    for (let i = 0; i <= 16; i++) {
      const u = i / 16, x = lerp(-hw, hw, u), wave = Math.sin(u * Math.PI * 3 + t * 2.4) * 9;
      top.push([x, -hh * 0.75 + wave]); bot.push([x, hh * 0.75 + wave]);
    }
    wash(g, top.concat(bot.reverse()), { t, color: C.sky, alpha: 0.42, seed: 1520 + c.id, edge: true, edgeW: 2, edgeAlpha: 0.25, blobs: 2, step: 16 });
    thin(g, top, { t, seed: 1525 + c.id, w: 1.8, color: rgba(C.ink, 0.6) });
  } else if (c.form === 'F7') {
    poly(g, [[-hw + 8, -hh + 12], [hw + 8, -hh + 12], [hw + 8, hh + 12], [-hw + 8, hh + 12]],
      { t, wobble: 1.6, seed: 1530 + c.id, fillColor: rgba(C.clayDk, 0.16), ink: null });
    poly(g, [[-hw, -hh], [hw, -hh], [hw, hh], [-hw, hh]],
      { t, wobble: 3.0, seed: 1531 + c.id, fillColor: rgba(C.creamLite, 0.92), ink: rgba(C.ink, 0.55), w: 1.6 });
  } else if (c.form === 'F8') {
    poly(g, [[-hw, -hh], [hw - 10, -hh], [hw, -hh + 12], [hw, hh - 8], [hw - 14, hh], [-hw + 9, hh], [-hw, hh - 11], [-hw, -hh + 14]],
      { t, wobble: 2.2, seed: 1540 + c.id, fillColor: C.clayDk, ink: rgba(C.ink, 0.7), w: 1.8 });
  } else if (c.form === 'F12') {
    const words = c.text.split(' ');
    let x = -width / 2;
    g.font = fontOf(fontPx);
    for (let i = 0; i < words.length; i++) {
      const w = g.measureText(words[i]).width + 16;
      poly(g, [[x, -hh * 0.8], [x + w, -hh * 0.85], [x + w + 4, hh * 0.8], [x - 2, hh * 0.9]],
        { t, wobble: 4.0, seed: 1550 + c.id * 7 + i, fillColor: rgba(C.paper, 0.92), ink: rgba(C.clayDk, 0.5), w: 1.2 });
      x += w + 4;
    }
  }
}

function formObjectDecor(g, c, fontPx, t, width) {
  if (c.form !== 'F10') return;
  const s = c.text.toLowerCase(), hw = width / 2;
  if (s.includes('sky') || s.includes('fly') || s.includes('plane')) {
    const pl = [[hw + 8, -8], [hw + 42, 14], [hw + 14, 8], [hw + 10, 12], [hw - 4, 22]];
    fillPoly(g, resample(pl, 4, true), rgba(C.ochre, 0.85), 1);
    contour(g, pl, { t, seed: 1560 + c.id, w: 1.4, color: C.ink, wobble: 0.5 });
  } else if (s.includes('sea') || s.includes('wave')) {
    for (let i = 0; i < 2; i++) {
      const pts = [];
      for (let j = 0; j <= 14; j++) { const x = -hw + (j / 14) * width; pts.push([x, fontPx * 0.55 + i * 10 + Math.sin(x * 0.045 + t * 2 + i) * 4]); }
      thin(g, pts, { t, seed: 1580 + c.id * 3 + i, w: 1.6, color: rgba(C.teal, 0.8) });
    }
  }
}

function glyph(g, ch, x, y, rot, fontPx, tex, c, t) {
  g.save(); g.translate(x, y); g.rotate(rot);
  g.font = fontOf(fontPx); g.textAlign = 'center'; g.textBaseline = 'middle';
  if (c.form === 'F2') { g.strokeStyle = tex.ink; g.lineWidth = tex.strokeW; g.strokeText(ch, 0, 0); }
  else if (c.form === 'F3') {
    g.fillStyle = tex.ink; g.fillText(ch, 0, 0);
    for (let i = 0; i < 3; i++) thin(g, [[-fontPx * 0.3, -fontPx * 0.22 + i * fontPx * 0.2], [fontPx * 0.32, -fontPx * 0.26 + i * fontPx * 0.2]], { t, seed: 1600 + c.id * 5 + i, w: 1.5, color: rgba(C.paper, 0.75) });
  } else if (c.form === 'F8') { g.fillStyle = C.creamLite; g.fillText(ch, 0, 0); }
  else if (c.form === 'F11') {
    g.strokeStyle = tex.ink; g.lineWidth = tex.strokeW; g.strokeText(ch, -2.4, -2.0);
    g.fillStyle = tex.fill; g.globalAlpha *= 0.6; g.fillText(ch, 0, 0); g.globalAlpha /= 0.6;
    g.strokeStyle = tex.ink; g.strokeText(ch, 2.4, 2.0);
  } else {
    if (tex.wet) { g.fillStyle = tex.fill; g.globalAlpha *= 0.72; g.fillText(ch, 0, 1.5); g.globalAlpha /= 0.72; }
    g.fillStyle = tex.ink; g.fillText(ch, 0, 0);
    g.strokeStyle = rgba(C.ink, 0.32); g.lineWidth = tex.strokeW * 0.55; g.strokeText(ch, 0, 0);
  }
  g.restore();
}

function drawCard(g, c, t) {
  const age = t - c.start, left = c.end - t, tail = c.tailException;
  const S = enterState(c, age);
  if (!tail && left < 0.30) {
    const E = exitState(c, left);
    S.alpha *= E.alpha; S.scale *= E.scale;
    S.dx += E.dx; S.dy += E.dy; S.rot += E.rot;
    S.clip = Math.min(S.clip, E.clip); S.scatter = Math.max(S.scatter, E.scatter);
    S.flip = Math.max(S.flip, E.flip); S.rise = Math.max(S.rise, E.rise);
    S.swirl = Math.max(S.swirl, E.swirl); S.bubble = Math.max(S.bubble, E.bubble);
    S.circleClip = Math.min(S.circleClip === 0 ? 1 : S.circleClip, E.circleClip === 0 ? 1 : E.circleClip);
  }
  if (S.alpha < 0.004 || S.scale < 0.004) return;

  const tex = TEX[c.texture] || TEX.dry;
  const fontPx = BASE_PX * Math.min(c.kf, KF_CAP) * (1 + 0.10 * pulse(t)) * (1 + (noise1(t * 12 + c.id, 3) - 0.5) * 0.022);
  const [zx, zy, zrot] = ZONES[c.zone] || ZONES.Z5;
  const wobX = Math.sin((t / (BEAT * 2)) * TAU + c.id) * 9 + pulse(t) * 4;
  const wobY = Math.cos((t / (BEAT * 2)) * TAU + c.id * 0.7) * 6;
  let x, y;
  if (BAND) {
    // `slot` (0..11) is authored by the card builder; `bandCol/bandRow` are
    // precomputed for 9:16 so the split cards of one phrase sit left→right in
    // the same row instead of scattering across a 1080-wide caption band.
    const zi = Number.isInteger(c.slot) ? c.slot : Math.max(0, ZONE_NAMES.indexOf(c.zone));
    if (BAND.rows) {
      const col = Number.isInteger(c.bandCol) ? c.bandCol : zi % 3;
      const row = Number.isInteger(c.bandRow) ? c.bandRow : Math.floor(zi / 3) % 2;
      x = BAND.xMin + ((col + 0.5) / 3) * (BAND.xMax - BAND.xMin) + S.dx + wobX;
      y = (BAND.y ?? 1700) + (row - 0.5) * (BAND.rowGap ?? 76) + S.dy + wobY;
    } else {
      x = BAND.xMin + ((zi + 0.5) / 12) * (BAND.xMax - BAND.xMin) + S.dx + wobX;
      y = (BAND.y ?? 900) + ((zi % 3) - 1) * (BAND.jitterY ?? 28) + S.dy + wobY;
    }
    if (c.tailException) x = W / 2;      // the closing statement owns the centre
  } else {
    x = zx * W + S.dx + wobX;
    y = zy * H + S.dy + wobY;
  }

  g.save(); g.setTransform(1, 0, 0, 1, 0, 0);
  g.font = fontOf(fontPx);
  const textW = g.measureText(c.text).width + 14 * (c.text.length - 1) * 0.12;
  const halfW = textW / 2 + 42, halfH = fontPx * 0.95 + 26;
  const xMin = halfW + MARGIN_X, xMax = W - halfW - MARGIN_X;
  const yMin = halfH + MARGIN_Y, yMax = H - halfH - MARGIN_Y;
  x = xMin <= xMax ? clamp(x, xMin, xMax) : W / 2;
  y = yMin <= yMax ? clamp(y, yMin, yMax) : H / 2;
  const HB = HERO_BOX;
  // In caption-band mode the band itself already clears the character, so the
  // centred HERO_BOX (authored for the music films) must not yank cards upward.
  if (!BAND && x + halfW > HB.x0 && x - halfW < HB.x1 && y + halfH > HB.y0 && y - halfH < HB.y1) {
    const up = HB.y0 - halfH - 24, down = HB.y1 + halfH + 24;
    y = up > yMin ? up : (down < yMax ? down : y);
    y = clamp(y, yMin, yMax);
  }
  if (!BAND && c.zone === 'Z5') y = H * 0.24;
  if (!BAND && c.zone === 'Z12') { x = W * 0.5 + Math.sin(t * 0.9) * 210; y = H * 0.30 + Math.cos(t * 1.1) * 70; }
  g.translate(x, y);
  // Portrait caption bands keep lettering upright; the forms/entrances still
  // rotate, pulse and boil, so no card is static.
  g.rotate((BAND?.rows ? 0 : zrot) + S.rot + S.swirl * 0.10);
  const flipS = S.flip > 0.001 ? Math.max(0.06, Math.abs(Math.cos(S.flip * Math.PI * 0.5))) : 1;
  g.scale(S.scale * flipS, S.scale);
  g.globalAlpha *= clamp(S.alpha);

  const clipK = Math.min(S.clip, S.circleClip === 0 ? 1 : S.circleClip);
  if (clipK < 0.995) {
    const w = textW + 90, h = fontPx * 2.4;
    g.beginPath();
    if (S.circleClip > 0 && S.circleClip < 1) g.arc(0, 0, Math.max(4, w * 0.6 * S.circleClip), 0, TAU);
    else g.rect(-w / 2, -h / 2, w * clipK, h);
    g.clip();
  }
  if (tex.wet) softPatch(g, 0, 0, textW * 0.60, fontPx * 1.0, { color: c.texture === 'bright' ? C.ochre : C.sky, alpha: 0.16, rings: 3, seed: c.id });
  const backW = textW + 40;
  formBack(g, c, fontPx, tex, t, backW);
  formObjectDecor(g, c, fontPx, t, backW);

  const chars = [...c.text];
  const widths = chars.map((ch) => g.measureText(ch).width);
  const total = widths.reduce((a, b) => a + b, 0) + 2 * (chars.length - 1);
  const b = boil(t);
  let cx = -total / 2;
  for (let i = 0; i < chars.length; i++) {
    const ch = chars[i], w = widths[i];
    const jx = (noise1(i * 3.7 + b, c.id) - 0.5) * 2.6, jy = (noise1(i * 5.1 + b, c.id + 1) - 0.5) * 2.6;
    let gx = cx + w / 2 + jx, gy = jy;
    let rot = (noise1(i * 7.3 + b, c.id + 2) - 0.5) * 0.05;
    const scatter = Math.max(S.scatter, S.swirl * 0.8, (c.form === 'F4' ? 0.55 : 0));
    if (scatter > 0.001) {
      gx += (noise1(i * 11.1, c.id + 3) - 0.5) * 22 * scatter + S.swirl * 34 * (i / Math.max(1, chars.length));
      gy += (noise1(i * 13.7, c.id + 4) - 0.5) * 20 * scatter - S.swirl * 22;
      rot += (noise1(i * 17.3, c.id + 5) - 0.5) * 0.28 * scatter;
    }
    if (!BAND?.rows && c.zone === 'Z10') {
      const a = -0.9 + (i / Math.max(1, chars.length - 1)) * 1.8;
      gx = Math.sin(a) * (total * 0.48); gy = -Math.cos(a) * 92 + 92; rot += a * 0.35;
    } else if (!BAND?.rows && c.zone === 'Z11') {
      gx = jx; gy = -total * 0.42 + i * (fontPx * 0.92);
      rot += (noise1(i * 9.1 + b, c.id) - 0.5) * 0.05;
    }
    glyph(g, ch, gx, gy, rot, fontPx, tex, c, t);
    cx += w + 2;
  }
  if (S.rise > 0.02) {
    const pts = [];
    for (let j = 0; j <= 14; j++) { const u = j / 14; pts.push([-textW * 0.6 + u * textW * 1.2, fontPx * (1.05 - S.rise * 0.5) + Math.sin(u * Math.PI * 3 + t * 3) * 8]); }
    thin(g, pts, { t, seed: 1700 + c.id, w: 2.4, color: rgba(C.teal, 0.7) });
  }
  if (S.bubble > 0.02) {
    for (let i = 0; i < 4; i++) {
      const bx = -textW * 0.4 + i * textW * 0.26, by = -fontPx * 0.7 - S.bubble * (40 + i * 18);
      contour(g, Array.from({ length: 10 }, (_, k) => [bx + Math.cos((k / 10) * TAU) * (7 + i), by + Math.sin((k / 10) * TAU) * (7 + i)]),
        { t, seed: 1720 + c.id * 5 + i, w: 1.2, color: rgba(C.sky, 0.8), wobble: 0.3 });
    }
  }
  if (tex.grain > 0.5) {
    for (let i = 0; i < 7; i++) {
      const gx = (noise1(i * 4.3 + b, c.id + 21) - 0.5) * textW * 1.1, gy = (noise1(i * 6.1 + b, c.id + 22) - 0.5) * fontPx * 1.3;
      thin(g, [[gx, gy], [gx + 7, gy - 2]], { t, seed: 1740 + c.id * 8 + i, w: 1.1, color: rgba(C.paperDeep, 0.45 * tex.grain) });
    }
  }
  g.restore();
}

export function drawSubtitles(g, t) {
  // In 9:16 the closing statement owns the whole caption band; otherwise the
  // three remaining split cards would collide with its giant lettering.
  const tail = VERTICAL && CARDS.find((c) => c.tailException && t >= c.start && t < c.end);
  for (const c of CARDS) {
    if (tail && c !== tail) continue;
    if (t >= c.start && t < c.end) drawCard(g, c, t);
  }
}
